import{_ as a,o as n,a as l,b as p}from"./app.DKoEZOcr.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"语言扩展层","link":"/guide/programming_guide/language_extension/language_extension"},{"text":"SIMD与SIMT混合编程BuiltIn关键字","link":"/guide/programming_guide/language_extension/simd_simt_hybrid_builtin_keywords"}]},"headers":[],"relativePath":"guide/programming_guide/language_extension/simd_simt_hybrid_builtin_keywords.md","filePath":"guide/programming_guide/language_extension/simd_simt_hybrid_builtin_keywords.md","outlineHeaders":[{"level":2,"title":"函数执行空间限定符","slug":"函数执行空间限定符","link":"#函数执行空间限定符"},{"level":2,"title":"VF函数执行限定符","slug":"VF函数执行限定符","link":"#VF函数执行限定符"},{"level":3,"title":"__simt_vf__","slug":"__simt_vf__","link":"#__simt_vf__"},{"level":3,"title":"__simt_callee__","slug":"__simt_callee__","link":"#__simt_callee__"},{"level":3,"title":"__simd_vf__与__simd_callee__","slug":"__simd_vf__与__simd_callee__","link":"#__simd_vf__与__simd_callee__"},{"level":2,"title":"地址空间限定符","slug":"地址空间限定符","link":"#地址空间限定符"},{"level":2,"title":"核函数（Kernel）配置","slug":"核函数（Kernel）配置","link":"#核函数（Kernel）配置"},{"level":3,"title":"核函数（Kernel）定义","slug":"核函数（Kernel）定义","link":"#核函数（Kernel）定义"},{"level":3,"title":"__launch_bounds__(N)","slug":"__launch_bounds__(N)","link":"#__launch_bounds__(N)"},{"level":3,"title":"<<<>>>调用","slug":"<<<>>>调用","link":"#<<<>>>调用"},{"level":2,"title":"VF函数的asc_vf_call调用","slug":"VF函数的asc_vf_call调用","link":"#VF函数的asc_vf_call调用"},{"level":3,"title":"SIMT VF的asc_vf_call调用","slug":"SIMT-VF的asc_vf_call调用","link":"#SIMT-VF的asc_vf_call调用"},{"level":3,"title":"SIMD VF的asc_vf_call调用","slug":"SIMD-VF的asc_vf_call调用","link":"#SIMD-VF的asc_vf_call调用"},{"level":3,"title":"SIMT VF与SIMD VF的调用差异","slug":"SIMT-VF与SIMD-VF的调用差异","link":"#SIMT-VF与SIMD-VF的调用差异"},{"level":2,"title":"内置变量","slug":"内置变量","link":"#内置变量"},{"level":3,"title":"不同层级的内置变量使用限制","slug":"不同层级的内置变量使用限制","link":"#不同层级的内置变量使用限制"},{"level":2,"title":"内置数据类型","slug":"内置数据类型","link":"#内置数据类型"},{"level":2,"title":"运算符","slug":"运算符","link":"#运算符"}],"lastUpdated":1787050286000}'),t={name:"guide/programming_guide/language_extension/simd_simt_hybrid_builtin_keywords.md"};function c(_,s,e,d,i,h){return n(),l("div",null,[...s[0]||(s[0]=[p(`<div><article class="markdown-body"><h1>SIMD&amp;SIMT BuiltIn关键字<span id="ZH-CN_TOPIC_0000002593949295"></span></h1><h2 id="函数执行空间限定符">函数执行空间限定符<span id="section1074418132518"></span><a class="header-anchor" href="#函数执行空间限定符">​</a></h2><p>SIMD与SIMT混合编程使用的函数执行空间限定符与SIMD编程一致，详细说明请参见<a href="simd_builtin_keywords.html#section1074418132518">SIMD BuiltIn关键字的函数执行空间限定符</a>。</p><h2 id="VF函数执行限定符">VF函数执行限定符<a class="header-anchor" href="#VF函数执行限定符">​</a></h2><h3 id="__simt_vf__">__simt_vf__<span id="section1009183746521"></span><a class="header-anchor" href="#__simt_vf__">​</a></h3><p>__simt_vf__用于标记SIMT VF入口函数，函数无返回值。函数定义示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simt_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">function_name</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">gm_param</span><span class="p">,</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">ubuf_param</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">scalar_param</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>SIMT VF函数定义中的关键修饰符说明如下：</p><table><thead><tr><th>修饰符</th><th>作用</th></tr></thead><tbody><tr><td>__simt_vf__</td><td>函数标识符，标识SIMT VF函数。</td></tr><tr><td>inline</td><td>建议内联，实际是否内联由编译器决定。</td></tr><tr><td>__gm__</td><td>内存空间修饰符，标识内存空间为GM。</td></tr><tr><td>__ubuf__</td><td>内存空间修饰符，标识内存空间为UB。</td></tr></tbody></table><p>只支持在核函数（Kernel）或__aicore__函数中调用SIMT VF函数，调用接口为<a href="../../../api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config.html#asc_vf_call%E8%B0%83%E7%94%A8">asc_vf_call</a>，示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">function_name</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">(</span><span class="n">blockDim</span><span class="p">),</span><span class="w"> </span><span class="n">arg1</span><span class="p">,</span><span class="w"> </span><span class="n">arg2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>SIMT VF函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="simt_builtin_keywords.html#section1835494915576">内置数据类型</a>（int32_t、uint32_t、float、half等）及其组成的指针、数组、结构体类型，且指针类型必须指向GM或者Unified Buffer（UB）内存。</li><li>函数返回类型必须是void。</li><li>SIMT VF内只能调用__simt_callee__函数或__callee__函数。</li></ul><h3 id="__simt_callee__">__simt_callee__<a class="header-anchor" href="#__simt_callee__">​</a></h3><p>__simt_callee__子函数是SIMT VF函数内部调用的辅助函数，函数内部可以使用SIMT内置变量。定义示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simt_callee__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">simt_helper</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">gm_param</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">ubuf_param</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">scalar_param</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">simt_helper</span><span class="p">(</span><span class="n">arg1</span><span class="p">,</span><span class="w"> </span><span class="n">arg2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>该函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="simt_builtin_keywords.html#section1835494915576">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数返回值只能是Ascend C的<a href="simt_builtin_keywords.html#section1835494915576">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数内只能调用__simt_callee__函数或__callee__函数。</li></ul><h3 id="__simd_vf__与__simd_callee__">__simd_vf__与__simd_callee__<a class="header-anchor" href="#__simd_vf__与__simd_callee__">​</a></h3><p>__simd_vf__用于标记SIMD VF入口函数，__simd_callee__是供SIMD VF内部调用子函数，详细说明请参见<a href="simd_builtin_keywords.html#section192521344610">SIMD BuiltIn关键字的SIMD VF函数标识符</a>。</p><h2 id="地址空间限定符">地址空间限定符<span id="section1624210295308"></span><a class="header-anchor" href="#地址空间限定符">​</a></h2><p>SIMD与SIMT混合编程使用的地址空间限定符与SIMD编程一致，详细说明请参见<a href="simd_builtin_keywords.html#section1624210295308">SIMD BuiltIn关键字的地址空间限定符</a>。</p><h2 id="核函数（Kernel）配置">核函数（Kernel）配置<a class="header-anchor" href="#核函数（Kernel）配置">​</a></h2><h3 id="核函数（Kernel）定义">核函数（Kernel）定义<a class="header-anchor" href="#核函数（Kernel）定义">​</a></h3><p>核函数（Kernel）是SIMD与SIMT混合编程的Device侧入口函数，负责协调整个算子的执行流程，包括VF的调度和调用。vector计算单元的混合编程场景下，函数定义语法为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">kernel_name</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">type</span><span class="o">*</span><span class="w"> </span><span class="n">param1</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">type</span><span class="o">*</span><span class="w"> </span><span class="n">param2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>关键修饰符说明如下：</p><ul><li>__global__：必需修饰符，作用为标识核函数（Kernel），表明可在Host侧通过&lt;&lt;&lt;...&gt;&gt;&gt;调用。</li><li>__vector__：必需修饰符，作用为标识函数是在Device侧AIV核上执行。</li></ul><p>核函数（Kernel）定义有以下几个约束：</p><ul><li>返回值类型必须是void；</li><li>入参支持指针类型（需使用__gm__修饰）和Ascend C内置数据类型；</li><li>指针参数必须是指向Global Memory上的内存地址，使用__gm__修饰。</li></ul><h3 id="__launch_bounds__(N)">__launch_bounds__(N)<a class="header-anchor" href="#__launch_bounds__(N)">​</a></h3><p>在多线程并发执行时，每个线程使用较少的寄存器可以让单个线程块内启动更多的线程，从而提升性能。因此，编译器会采用启发式算法，将寄存器溢出（register spilling）和指令数量控制在最低水平，同时尽量减少寄存器的使用量。应用程序可以通过在__global__函数定义中使用__launch_bounds__()限定符来限制启动边界（launch bounds），提供附加信息辅助编译器优化这一过程，这属于可选配置。</p><p>__launch_bounds__(N)：函数标记宏，在SIMT VF入口函数上可选配置，用于在编译期指定SIMT VF启动的最大线程数，参数N的取值范围为1到2048。若未配置__launch_bounds__，最大线程数默认为1024。</p><p>最大线程数决定了每个线程可分配的寄存器数量，具体对应关系请见下表，寄存器用于存储线程中的局部变量，若局部变量的个数超出寄存器个数，容易出现栈溢出等问题。建议最大线程数与启动VF任务的dim3线程数保持一致。</p><p><strong>表1</strong> __launch_bounds__(N)与每个线程可用寄存器个数的关系</p><table><thead><tr><th>N</th><th>每个线程可用寄存器个数</th></tr></thead><tbody><tr><td>1025~2048</td><td>16</td></tr><tr><td>513~1024</td><td>32</td></tr><tr><td>257~512</td><td>64</td></tr><tr><td>1~256</td><td>127</td></tr></tbody></table><h3 id="&lt;&lt;&lt;&gt;&gt;&gt;调用">&lt;&lt;&lt;&gt;&gt;&gt;调用<a class="header-anchor" href="#&lt;&lt;&lt;&gt;&gt;&gt;调用">​</a></h3><p>SIMD与SIMT混合编程是在SIMD编程模型的核函数（Kernel）执行流程基础上引入SIMT VF（Vector Function）子任务。核函数（Kernel）仍按SIMD编程方式在Host侧通过&lt;&lt;&lt;...&gt;&gt;&gt;启动，语法如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">kernel_name</span><span class="o">&lt;&lt;&lt;</span><span class="n">block_num</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ub_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">args</span><span class="p">...);</span>
</code></pre></div><p>内核调用符内的配置参数说明如下：</p><table><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>约束</th></tr></thead><tbody><tr><td>block_num</td><td>uint32_t</td><td>设置核函数（Kernel）启用的核数</td><td>取值范围[1, 65535]</td></tr><tr><td>dyn_ub_size</td><td>uint32_t</td><td>指定动态内存大小，单位为字节</td><td>不超过最大可配置值：256KB - 8KB - 32KB - 静态内存</td></tr><tr><td>stream</td><td>aclrtStream</td><td>用于维护异步操作执行顺序</td><td>无</td></tr></tbody></table><h2 id="VF函数的asc_vf_call调用">VF函数的asc_vf_call调用<a class="header-anchor" href="#VF函数的asc_vf_call调用">​</a></h2><h3 id="SIMT-VF的asc_vf_call调用">SIMT VF的asc_vf_call调用<a class="header-anchor" href="#SIMT-VF的asc_vf_call调用">​</a></h3><p>SIMD与SIMT混合编程以SIMD核函数（Kernel）作为Device侧入口，在核函数（Kernel）或<code>__aicore__</code>函数中通过<code>asc_vf_call</code>启动SIMT VF子任务，通过参数配置，启动指定数目的线程，执行指定的SIMT VF函数。其函数原型如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">auto</span><span class="w"> </span><span class="n">funcPtr</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="p">...</span><span class="w"> </span><span class="n">Args</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_vf_call</span><span class="p">(</span><span class="n">dim3</span><span class="w"> </span><span class="n">threadNums</span><span class="p">,</span><span class="w"> </span><span class="n">Args</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="p">...</span><span class="n">args</span><span class="p">)</span>
</code></pre></div><p>其中模板参数为指定的SIMT VF函数名以及SIMT VF函数参数，具体描述如下：</p><p><strong>表2</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>funcPtr</td><td>用于指定SIMT入口核函数（Kernel）。</td></tr><tr><td>Args</td><td>定义可变参数，用于传递实参到SIMT入口核函数（Kernel）。</td></tr></tbody></table><p><strong>表3</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>threadNums</td><td>输入</td><td>dim3结构，定义为{dimx，dimy，dimz}，用于指定SIMT线程块内线程数量。线程总数为dimx * dimy * dimz，该值的大小必须小于等于2048，建议为32的倍数。</td></tr><tr><td>args</td><td>输入</td><td>可变参数，用于传递实参到SIMT入口核函数（Kernel）。</td></tr></tbody></table><p>以下示例展示了SIMD与SIMT混合编程场景下如何使用asc_vf_call调用__simt_vf__函数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;simt_api/common_functions.h&quot;</span>
<span class="n">__simt_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_simt</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src1</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// simt代码</span>
<span class="w">    </span><span class="kt">int</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="n">dst</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">src0</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">src1</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="p">}</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// asc_vf_call启动SIMT VF子任务，函数名为：add_simt，配置blockDim为dim3{1024, 1, 1}</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">add_simt</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">{</span><span class="mi">1024</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">},</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><h3 id="SIMD-VF的asc_vf_call调用">SIMD VF的asc_vf_call调用<a class="header-anchor" href="#SIMD-VF的asc_vf_call调用">​</a></h3><p>使用<code>asc_vf_call</code>接口调用SIMD VF入口函数启动VF子任务，详细接口说明参见 <a href="../../../api/SIMD-API/basic_api/reg_vector_compute/vf_call/asc_vf_call.html">asc_vf_call接口说明</a>。</p><h3 id="SIMT-VF与SIMD-VF的调用差异">SIMT VF与SIMD VF的调用差异<a class="header-anchor" href="#SIMT-VF与SIMD-VF的调用差异">​</a></h3><p>SIMT VF与SIMD VF均通过<code>asc_vf_call</code>接口在核函数（Kernel）或<code>__aicore__</code>函数中启动VF子任务，但二者面向的并行执行模型不同：SIMT VF以线程为基本执行单元，实现线程级并行；SIMD VF基于矢量寄存器对连续数据实现数据级并行。执行模型的差异进一步决定了二者在调用形式上存在差异，具体如下表所示：</p><table><thead><tr><th>对比项</th><th>SIMT VF调用</th><th>SIMD VF调用</th></tr></thead><tbody><tr><td>VF入口函数标识</td><td>使用__simt_vf__修饰。</td><td>使用__simd_vf__修饰。</td></tr><tr><td>调用形式</td><td>asc_vf_call&lt;simt_func&gt;(dim3(threadNums), arg1, arg2, ...)</td><td>asc_vf_call&lt;simd_func&gt;(arg1, arg2, ...)</td></tr><tr><td>第一个运行时参数</td><td>必须传入dim3类型的线程配置，用于指定SIMT线程块内线程数量。</td><td>没有线程配置参数，调用参数从SIMD VF函数的第一个实参开始传入。</td></tr><tr><td>指针入参</td><td>支持指向GM或UB的指针，需按实际内存空间使用__gm__或__ubuf__修饰。</td><td>指针入参需使用__ubuf__地址空间限定符修饰，不能直接访问GM内存。</td></tr><tr><td>典型用途</td><td>处理复杂控制流、离散访存、线程级索引映射等不规则片段。</td><td>处理连续规整的向量计算片段。</td></tr></tbody></table><h2 id="内置变量">内置变量<span id="zh-cn_topic_0000002571575581_section13165113520576"></span><a class="header-anchor" href="#内置变量">​</a></h2><p>当前提供了以下仅在SIMT VF内可用的内置变量：</p><ul><li><p>gridDim<span id="zh-cn_topic_0000002571575581_li20760123812911"></span></p><p>内置全局变量，只能在SIMT VF函数中使用，表示整个计算任务在各个维度上分别由多少个线程块构成。gridDim.x &lt;= 65535；gridDim.y、gridDim.z必须为1。</p></li><li><p>blockDim<span id="zh-cn_topic_0000002571575581_li076017381191"></span></p><p>内置全局变量，在SIMT VF函数中可以直接使用，用于获取线程块中配置的线程的三维层次结构。blockDim.x，blockDim.y，blockDim.z分别表示线程块中三个维度的线程数，各个维度上线程数需满足blockDim.x * blockDim.y *blockDim.z &lt;= 2048。</p></li><li><p>blockIdx</p><p>内置全局变量，只能在SIMT VF函数中使用，用于获取块索引。表示当前线程所在的线程块在整个网格中的位置坐标。blockIdx.x的范围是0到gridDim.x - 1，blockIdx.y和blockIdx.z目前只能返回0。</p></li><li><p>threadIdx</p><p>内置全局变量，只能在SIMT VF函数中使用，用于获取当前线程在线程块内部的索引。threadIdx.x，threadIdx.y，threadIdx.z分别表示当前线程在3个维度的索引，threadIdx.x的范围为[0, blockDim.x)，threadIdx.y的范围为[0, blockDim.y)，threadIdx.z的范围为[0, blockDim.z)。线程块内线程的索引计算方式如下：</p><ul><li>对于一维线程块，线程块内线程的索引为threadIdx.x。</li><li>对于二维线程块，线程块内线程的索引为(threadIdx.x + threadIdx.y * blockDim.x)。</li><li>对于三维线程块，线程块内线程的索引为(threadIdx.x + threadIdx.y * blockDim.x + threadIdx.z * blockDim.x * blockDim.y)。</li></ul></li><li><p>warpSize</p><p>运行时变量，表示一个线程束（Warp）中的线程数量，当前为固定值32。</p></li></ul><p>SIMD核函数（Kernel）层级的内置变量参见<a href="./simd_builtin_keywords.html#%E5%86%85%E7%BD%AE%E5%8F%98%E9%87%8F">SIMD核函数（Kernel）层内置变量</a>。</p><h3 id="不同层级的内置变量使用限制">不同层级的内置变量使用限制<a class="header-anchor" href="#不同层级的内置变量使用限制">​</a></h3><p>Host侧&lt;&lt;&lt;...&gt;&gt;&gt;调用配置的是外层核函数（Kernel）的逻辑核数；SIMT VF内部的线程架构类内置变量描述的是SIMT VF子任务的线程层次。两类概念所属层级不同，不能混用，下表列出了SIMD核函数（Kernel）层级和SIMT VF线程层级中常见概念的差异。</p><table><thead><tr><th>内置变量或方法</th><th>所属层级</th><th>使用位置</th><th>含义</th></tr></thead><tbody><tr><td><code>AscendC::GetBlockNum()</code></td><td>SIMD核函数（Kernel）层级</td><td>核函数（Kernel）或<code>__aicore__</code>函数，SIMT VF内部不可见</td><td>获取Host侧&lt;&lt;&lt;...&gt;&gt;&gt;调用配置的核函数（Kernel）逻辑核数，即<code>block_num</code>。</td></tr><tr><td><code>AscendC::GetBlockIdx()</code></td><td>SIMD核函数（Kernel）层级</td><td>核函数（Kernel）或<code>__aicore__</code>函数，SIMT VF内部不可见</td><td>获取当前执行核函数（Kernel）的逻辑核索引。</td></tr><tr><td><code>gridDim</code></td><td>SIMT VF线程层级</td><td><code>__simt_vf__</code>或<code>__simt_callee__</code>函数，SIMT VF外部不可见</td><td>获取SIMT VF线程层次中的网格维度，表示本次SIMT VF子任务在各维度上的线程块数量。其值由Host侧&lt;&lt;&lt;...&gt;&gt;&gt;调用配置的核函数（Kernel）逻辑核数决定。</td></tr><tr><td><code>blockIdx</code></td><td>SIMT VF线程层级</td><td><code>__simt_vf__</code>或<code>__simt_callee__</code>函数，SIMT VF外部不可见</td><td>获取SIMT VF线程层次中的线程块索引，表示当前线程所在的SIMT线程块在VF执行网格中的位置。</td></tr><tr><td><code>blockDim</code></td><td>SIMT VF线程层级</td><td><code>__simt_vf__</code>或<code>__simt_callee__</code>函数，SIMT VF外部不可见</td><td>获取SIMT VF线程块内的线程三维结构，其值由调用SIMT VF时<code>asc_vf_call</code>的第一个<code>dim3</code>参数指定。</td></tr><tr><td><code>threadIdx</code></td><td>SIMT VF线程层级</td><td><code>__simt_vf__</code>或<code>__simt_callee__</code>函数，SIMT VF外部不可见</td><td>获取当前SIMT线程在线程块内部的索引。</td></tr></tbody></table><p>使用时需注意：</p><ul><li>SIMD侧核函数（Kernel）不能使用SIMT VF线程层级相关内置变量，SIMT VF也无法感知SIMD核函数（Kernel）层级的逻辑核编号或逻辑核数量。</li><li>如果SIMT VF需要使用外层SIMD流程中的逻辑核编号或逻辑核数量，建议在核函数（Kernel）或<code>__aicore__</code>函数中通过<code>AscendC::GetBlockIdx()</code>、<code>AscendC::GetBlockNum()</code>获取对应值后，以普通参数传入SIMT VF。</li></ul><h2 id="内置数据类型">内置数据类型<span id="zh-cn_topic_0000002571575581_section1880403364916"></span><span id="cn_topic_0000002571575581_section1880403364916"></span><a class="header-anchor" href="#内置数据类型">​</a></h2><p>SIMD与SIMT混合编程使用的内置数据类型与SIMT编程一致，详细说明请参见<a href="simt_builtin_keywords.html#section1835494915576">SIMT BuiltIn关键字的内置数据类型</a>。</p><h2 id="运算符">运算符<span id="zh-cn_topic_0000002571575581_section186787252339"></span><a class="header-anchor" href="#运算符">​</a></h2><p>SIMD与SIMT混合编程支持的运算符与SIMT编程一致，详细说明请参见<a href="simt_builtin_keywords.html#section186787252339">SIMT BuiltIn关键字的运算符</a>。</p></article></div>`,1)])])}const m=a(t,[["render",c]]);export{r as __pageData,m as default};
